"""
    Generates Lorenz strange attractor.
    """
def lorenz(
    num_points: Any = 15000,
    start: Any = [0.1, 0.1, 0.1],
    scaling_factor: Any = 20,
    delta: Any = 0.008,
    a: Any = 0.1,
    b: Any = 4.0,
    c: Any = 14.0,
    d: Any = 0.08
) -> object {
    verts = [];
    x = start[0];
    y = start[1];
    z = start[2];
    for i in range(0, num_points) {
        dx = (((-a * x) + (y * y)) - (z * z)) + (a * c);
        dy = (x * (y - (b * z))) + d;
        dz = z + (x * ((b * y) + z));
        x = x + (delta * dx);
        y = y + (delta * dy);
        z = z + (delta * dz);
        verts.extend(
            [(x * scaling_factor), (z * scaling_factor), (y * scaling_factor)]
        );
    }
    return verts;
}

