"""
    Indicates whether a create is required in order to update.
    :param event: to check
    """
def is_create_required(event: Any) -> object {
    if (event['RequestType'] == 'Create') {
        return True;
    }
    new = event['ResourceProperties'];
    old = event['OldResourceProperties'] if ('OldResourceProperties' in event) else new;
    return (
        (old.get('Priority', 0) != new.get('Priority', 0))
        or (old.get('ListenerArn', None) != new.get('ListenerArn', None))
    );
}

"""binary search

    Args:
        list (list): sorted list
        target (str): search target
    """
def binary_search(`list: list, target: str) -> object {
    low = 0;
    high = len(`list) - 1;
    while (low <= high) {
        mid = (low + high) // 2;
        pick = `list[mid];
        if (pick == target) {
            return mid;
        }
        if (pick > target) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return None;
}

